    col = len(grid[0])
    output = 1
    dp = [[[1, 1, 1, 1] for _ in range(col)]  for _ in range(row)]

    for i in range(row):
        for j in range(col):
            neighs = [(i, j - 1), (i - 1, j), (i - 1, j - 1), (i - 1, j + 1)]
            for k, (l, m) in enumerate(neighs):
                if 0 <= l < row and 0 <= m < col and grid[i][j] == grid[l][m]:
                    dp[i][j][k] += dp[l][m][k]
                output = max(output, max(dp[i][j]))

    return output
