    public int minPathNodes(
            java.util.List<java.util.List<Integer>> connections,
            int start,
            int destination,
            int broken,
            boolean allowBroken) {

        int n = connections.size();

        // If broken vertex is not allowed and is an endpoint,
        // no valid path exists.
        if (!allowBroken && (start == broken || destination == broken)) {
            return -1;
        }

        if (start == destination) {
            return 1;
        }

        int[] dist = new int[n];
        Arrays.fill(dist, -1);

        Queue<Integer> queue = new ArrayDeque<>();
        queue.offer(start);
        dist[start] = 0;

        while (!queue.isEmpty()) {
            int u = queue.poll();

            for (int v : connections.get(u)) {

                // Broken vertex cannot be used.
                if (!allowBroken && v == broken) {
                    continue;
                }

                if (dist[v] != -1) {
                    continue;
                }

                dist[v] = dist[u] + 1;

                if (v == destination) {
                    // dist = number of edges
                    // vertices = edges + 1
                    return dist[v] + 1;
                }

                queue.offer(v);
            }
        }

        return -1;
    }
