            const std::vector<int>& starts, const std::vector<int>& ends, int x) {
        if (starts.empty()) return {};

        std::map<int,int> events; 
        for (int i = 0 ; i < starts.size() ; i++) {
            events[starts[i]]++;
            events[ends[i]]--;
        }

        int active = 0;
        int previous = events.begin()->first;
        std::vector<std::vector<int>> ans;

        for (auto &[time, delta] : events) {
            if (previous < time && active == x) {
                if (!ans.empty() && ans.back()[1] == previous) {
                    ans.back()[1] = time;
                } else {
                    ans.push_back({previous, time});
                }
            }
            active += delta;
            previous = time;
        }

        return ans;
    }
