public:
    long long solution(long long n) {
        std::string digits = std::to_string(n);
        int len = digits.size();

        int cliff = -1;
        for (int i = 0 ; i < len - 1; i++) {
            if (digits[i] > digits[i+1]) {
                cliff = i;
                break;
            }
        }
        if (cliff == -1) return n;
        while (cliff > 0 && digits[cliff-1] == digits[cliff]) cliff--;
        digits[cliff]--;
        for(int i = cliff + 1; i < len ; i++) digits[i] = '9';
        return std::stoll(digits);
    }
};
