def solution(recipes, inventory, target_item, target_quantity):
    inventory = dict(inventory)
    making = set()

    def canMake(item, quantity):
        if quantity <= 0:
            return True

        available = inventory.get(item, 0)
        used = min(quantity, available)
        inventory[item] = available - used
        still_needed = quantity - used

        if still_needed == 0:
            return True

        if item not in recipes:
            return False

        if item in making:
            return False

        making.add(item)
        success = True

        for ing, q in recipes[item]:
            total = q * still_needed
            if not canMake(ing, total):
                success = False
                break

        making.remove(item)
        return success

    return canMake(target_item, target_quantity)
