def valid_single_worker_schedule(
    n: int,
    edges: List[Tuple[int, int]]
) -> List[int]:
    graph = defaultdict(list)
    indegree = [0] * n

    for u, v in edges:
        graph[u].append(v)
        indegree[v] += 1

    heap = [
        task
        for task in range(n)
        if indegree[task] == 0
    ]
    heapq.heapify(heap)

    order = []

    while heap:
        u = heapq.heappop(heap)
        order.append(u)

        for v in graph[u]:
            indegree[v] -= 1

            if indegree[v] == 0:
                heapq.heappush(heap, v)

    if len(order) != n:
        return []

    return order

